<style>
    .hv-booking-panel .hv-price-card{padding:0!important;overflow:hidden;border:1px solid #e4eaf1;border-radius:14px;background:#fff;min-width:0}
    .hv-price-details>summary{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 16px;font-size:14px;font-weight:700;color:#142b49;cursor:pointer;list-style:none;background:#f8fafc}
    .hv-price-details>summary::-webkit-details-marker{display:none}.hv-price-chevron{font-size:20px;color:#64748b;transition:transform .15s}.hv-price-details[open] .hv-price-chevron{transform:rotate(180deg)}
    .hv-price-body{padding:14px 16px 16px;min-width:0}.hv-price-context{margin:0;color:#142b49;font-size:12px;line-height:1.55;overflow-wrap:anywhere}
    .hv-price-context strong,.hv-price-context>span{display:block}.hv-price-context>span{margin-top:3px;color:#64748b;font-weight:400}
    .hv-price-stay{display:flex;gap:7px;align-items:center;margin:10px 0 12px;font-size:11px;color:#64748b}
    .hv-nightly-scroll{max-height:300px;overflow-y:auto;min-width:0}.hv-nightly-table{width:100%;table-layout:fixed;border-collapse:collapse;font-size:12px;line-height:1.5}
    .hv-nightly-table th{padding:8px 0;color:#64748b;font-size:10px;font-weight:500;text-align:left;border-bottom:1px solid #e4eaf1;vertical-align:bottom}
    .hv-nightly-table th:first-child{width:28%}.hv-nightly-table th:nth-child(2){width:38%}.hv-nightly-table th:last-child{width:34%}
    .hv-nightly-table td{padding:12px 0;color:#243247;border-bottom:1px solid #edf0f4;vertical-align:top;overflow-wrap:anywhere}
    .hv-nightly-table th+th,.hv-nightly-table td+td{padding-left:7px;text-align:right;font-variant-numeric:tabular-nums}
    .hv-nightly-table td:last-child{font-weight:650}.hv-nightly-table small{display:block;margin-top:6px;font-size:10px;color:#64748b;font-weight:400;line-height:1.5}
    .hv-price-date,.hv-price-unit,.hv-price-amount{display:block;line-height:1.5;white-space:nowrap}
    .hv-price-multiplier{display:block;color:#64748b;font-size:11px;margin-top:4px;line-height:1.5;white-space:nowrap}
    .hv-nightly-table .hv-price-surcharge{overflow-wrap:anywhere}
    .hv-price-card .hv-price-totals{margin:4px 0 0}.hv-price-card .hv-price-totals>div{display:flex;justify-content:space-between;align-items:baseline;gap:12px;padding:13px 0;font-size:12px}
    .hv-price-card .hv-price-totals dt{color:#64748b}.hv-price-card .hv-price-totals dd{margin:0;text-align:right;font-weight:650;color:#142b49;font-variant-numeric:tabular-nums;overflow-wrap:anywhere;min-width:0}
    .hv-price-card .hv-price-totals>.hv-price-grand-total{border-top:1px solid #dce5ef;padding:15px 0 3px}.hv-price-card .hv-price-grand-total dt{color:#142b49;font-weight:700;font-size:13px}.hv-price-card .hv-price-grand-total dd{color:#1d4ed8;font-size:21px;font-weight:750}
    .hv-price-note{margin:10px 0 0;font-size:11px;color:#64748b;line-height:1.65;overflow-wrap:anywhere}
    @media(max-width:420px){.hv-price-body{padding:12px}.hv-price-details>summary{padding:13px 12px}.hv-nightly-table{font-size:11px}.hv-nightly-table th{font-size:9px}.hv-price-card .hv-price-grand-total dd{font-size:19px}}
    @media(max-width:360px){.hv-price-body{padding:10px}.hv-nightly-table{font-size:10px}.hv-nightly-table th+th,.hv-nightly-table td+td{padding-left:4px}.hv-price-multiplier{font-size:10px}}
</style>
